    controls=[("O", "open / close the replay", "O", "открыть / закрыть повтор"), ("P", "pause / play", "P", "пауза / воспроизведение"), ("Left / Right (hold)", "scrub back / forward", "Влево / вправо (удерживать)", "перемотка назад / вперёд"),
              ("Up / Down", "speed x0.1 ... x2", "Вверх / вниз", "скорость x0,1 ... x2"), ("Mouse", "turn the camera around you", "Мышь", "повернуть камеру вокруг себя"), ("Wheel", "camera nearer / farther", "Колесо", "камера ближе / дальше"), ("R", "restart", "R", "с начала")],
    settings=[("Replay key O / L", "O", "Клавиша повтора O / L", "O"), ("Recorded seconds 5-30", "10", "Секунд записи 5-30", "10"), ("Samples per second 10 / 20 / 30", "20", "Кадров в секунду 10 / 20 / 30", "20"),
              ("Max recorded objects 20-150", "80", "Предметов в записи 20-150", "80"), ("Recording radius 10-80 m", "30 m", "Радиус записи 10-80 м", "30 м"), ("Start at the beginning / 4 s before the busiest moment", "beginning", "Начинать с начала / за 4 с до самого бурного момента", "с начала"),
              ("At the end: loop / pause", "loop", "В конце: по кругу / пауза", "по кругу"), ("Replay the destruction: on / off", "on", "Повторять разрушения: да / нет", "да"), ("Map radius 10-50 m", "25 m", "Радиус карты 10-50 м", "25 м"),
              ("Camera distance 2-10 m", "4.5 m", "Расстояние камеры 2-10 м", "4,5 м"), ("REC indicator", "show", "Значок записи", "показывать")],
