    settings=[("Strength x0.3-x3", "x1", "Сила x0,3-x3", "x1"), ("Size (top radius) 4-20 m", "8 m", "Размер (радиус наверху) 4-20 м", "8 м"), ("Lifetime 10-180 s", "40 s", "Время жизни 10-180 с", "40 с"),
              ("Travel speed 1-12 m/s", "4", "Скорость движения 1-12 м/с", "4"), ("Movement: wanders / follows your aim", "wanders", "Движение: бродит / идёт за прицелом", "бродит"),
              ("Lifts vehicles", "yes", "Поднимает машины", "да"), ("Lifts the player", "yes", "Поднимает игрока", "да"), ("Tears buildings", "yes", "Рвёт постройки", "да")],
