mod("tsunami", tags="Tool",
    title="Tsunami", title_ru="Цунами",
    tagline="A wall of water. Run.", tagline_ru="Стена воды. Бегите.",
    intro="A conch horn that calls a tsunami from where you look. A siren warns while the wave rises on the horizon, then a wall of water rolls in, throws cars, carries away objects and you, tears buildings apart, floods the ground and finally runs back.",
    intro_ru="Раковина-рог, которая вызывает цунами оттуда, куда вы смотрите. Воет сирена, волна поднимается на горизонте, потом накатывает стена воды, бросает машины, уносит предметы и вас, разрывает дома, затапливает землю и в конце откатывается назад.",
    features=["Warning siren with distance and height of the wave", "A 400 m wide, 14 m high wall of water with a foam crest and spray", "A current strong enough to throw cars; carries objects, debris and players", "Tears wood and brick buildings apart over the whole wave height", "Flood behind the wave, then backwash", "Any water in the level turns rough during the event and calms down afterwards"],
    features_ru=["Сирена с расстоянием и высотой волны", "Стена воды шириной 400 м и высотой 14 м с гребнем пены и брызгами", "Течение бросает машины, уносит предметы, обломки и игроков", "Разрывает деревянные и кирпичные дома по всей высоте волны", "Затопление за волной, потом откат", "Вода на уровне бушует во время волны и потом успокаивается"],
    controls=[("LMB", "call a tsunami from where you look", "ЛКМ", "вызвать цунами оттуда, куда смотрите"), ("RMB", "call it off", "ПКМ", "отменить волну")],
    settings=[("Wave height 3-25 m", "14 m", "Высота волны 3-25 м", "14 м"), ("Wave speed 8-35 m/s", "18 m/s", "Скорость волны 8-35 м/с", "18 м/с"), ("Flood level behind it 0-4 m", "1.5 m", "Уровень затопления 0-4 м", "1,5 м"),
              ("Damage to buildings x0-x3", "x1.5", "Разрушение построек x0-x3", "x1,5"), ("Warning siren", "on", "Сирена", "вкл")],
    limits=["Mods cannot raise the game's water level, so the wave and the flood are drawn and push like a strong current", "The water level is measured from the ground where you stood when you called it: hills and roofs above it stay dry"],
    limits_ru=["Моды не могут поднять уровень воды в игре, поэтому волна и затопление нарисованы и толкают как сильное течение", "Уровень воды отсчитывается от земли там, где вы стояли, когда её вызвали: холмы и крыши выше остаются сухими"])

